import { Outlet, useNavigate } from "react-router-dom";

function MainLayout() {
  const navigate = useNavigate();

  return (
    <div style={{
      maxWidth: "420px",
      margin: "0 auto",
      background: "#F6FFF4",
      minHeight: "100vh"
    }}>

      {/* 상단 */}
      <div style={{
        padding: "15px",
        fontSize: "20px",
        fontWeight: "bold",
        color: "#4CAF50"
      }}>
        READLY 📚
      </div>

      {/* 페이지 */}
      <Outlet />

      {/* 하단 네비 */}
      <div style={{
        position: "fixed",
        bottom: 0,
        width: "100%",
        maxWidth: "420px",
        display: "flex",
        justifyContent: "space-around",
        padding: "12px",
        background: "white",
        borderTop: "1px solid #eee"
      }}>
        <button onClick={() => navigate("/")}>홈</button>
        <button onClick={() => navigate("/ai")}>AI</button>
        <button onClick={() => navigate("/community")}>모임</button>
        <button onClick={() => navigate("/profile")}>MY</button>
      </div>

    </div>
  );
}

export default MainLayout;
